using System;
using System.IO;
using SharpGLTF.Schema2;
using SharpGLTF.Scenes;
using SharpGLTF.Geometry;
using SharpGLTF.Geometry.VertexTypes;
using SharpGLTF.Materials;
using System.Numerics;

var scene = new SceneBuilder("test");
var mesh = new MeshBuilder<VertexPositionNormal>("box");
var mat = new MaterialBuilder("default").WithUnlitShader();
var prim = mesh.UsePrimitive(mat);
prim.AddTriangle(
    new VertexPositionNormal(new Vector3(0,0,0), Vector3.UnitZ),
    new VertexPositionNormal(new Vector3(1,0,0), Vector3.UnitZ),
    new VertexPositionNormal(new Vector3(0,1,0), Vector3.UnitZ));
var node = new SharpGLTF.Scenes.NodeBuilder("n");
scene.AddRigidMesh(mesh, node);
var model = scene.ToGltf2();

// Test WriteGLB to stream
using var ms = new MemoryStream();
model.WriteGLB(ms);
Console.WriteLine($"GLB bytes: {ms.Length}");

// Test WriteGLB returning ArraySegment
var seg = model.WriteGLB(new WriteSettings());
Console.WriteLine($"GLB segment: {seg.Count}");

// Test SaveGLTF
var tmpDir = Path.Combine(Path.GetTempPath(), "gltf_test_" + Guid.NewGuid());
Directory.CreateDirectory(tmpDir);
var gltfPath = Path.Combine(tmpDir, "test.gltf");
model.SaveGLTF(gltfPath);
var gltfBytes = File.ReadAllBytes(gltfPath);
Console.WriteLine($"GLTF bytes: {gltfBytes.Length}");
Directory.Delete(tmpDir, true);

Console.WriteLine("All OK!");
EOF
